const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const english = escapeHtml($json['英文原文']);
const author = escapeHtml($json['作者']);
const translation = escapeHtml($json['中文翻譯']);
const inspiration = escapeHtml($json['今日行動建議與啟發']);

const html = `<!doctype html>
<html lang="zh-Hant">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#102d27">
  <title>今日哲思</title>
  <style>
    :root { --ink:#102d27; --paper:#f5f0e5; --gold:#c8994b; --soft:#dfe9e2; }
    * { box-sizing:border-box; }
    body { margin:0; min-height:100vh; color:var(--ink); background:var(--paper); font-family:"Noto Serif TC","Songti TC","Times New Roman",serif; overflow-x:hidden; }
    body::before { content:""; position:fixed; inset:0; pointer-events:none; opacity:.55; background:radial-gradient(circle at 16% 18%,rgba(200,153,75,.20),transparent 32%),radial-gradient(circle at 85% 82%,rgba(16,45,39,.16),transparent 34%); }
    .shell { position:relative; min-height:100vh; display:grid; place-items:center; padding:clamp(24px,5vw,72px); }
    .frame { width:min(920px,100%); border:1px solid rgba(16,45,39,.24); padding:clamp(8px,1.4vw,14px); box-shadow:0 30px 80px rgba(16,45,39,.15); background:rgba(245,240,229,.65); backdrop-filter:blur(8px); }
    .card { position:relative; min-height:600px; display:flex; flex-direction:column; justify-content:space-between; gap:42px; padding:clamp(30px,7vw,84px); border:1px solid rgba(16,45,39,.16); background:linear-gradient(145deg,rgba(255,255,255,.78),rgba(223,233,226,.5)); overflow:hidden; }
    .card::after { content:"“"; position:absolute; right:3%; top:-9%; color:rgba(200,153,75,.14); font-size:clamp(180px,36vw,360px); line-height:1; pointer-events:none; }
    .topline { display:flex; align-items:center; justify-content:space-between; gap:20px; font:600 12px/1.2 system-ui,sans-serif; letter-spacing:.24em; text-transform:uppercase; }
    .mark { display:flex; align-items:center; gap:12px; }
    .mark::before { content:""; width:34px; height:2px; background:var(--gold); }
    #date { color:rgba(16,45,39,.58); letter-spacing:.08em; }
    main { position:relative; z-index:1; }
    .translation { max-width:720px; margin:0; font-size:clamp(32px,6vw,62px); font-weight:600; line-height:1.45; letter-spacing:.05em; text-wrap:balance; }
    .author { margin:26px 0 0; color:var(--gold); font:600 clamp(13px,1.8vw,16px)/1.5 system-ui,sans-serif; letter-spacing:.12em; }
    .original { max-width:650px; margin:24px 0 0; color:rgba(16,45,39,.62); font-size:clamp(15px,2vw,19px); font-style:italic; line-height:1.7; }
    .footer { display:grid; grid-template-columns:1fr auto; gap:28px; align-items:end; padding-top:28px; border-top:1px solid rgba(16,45,39,.18); }
    .label { margin:0 0 9px; color:rgba(16,45,39,.55); font:700 11px/1.2 system-ui,sans-serif; letter-spacing:.22em; }
    .action { margin:0; font-size:clamp(18px,2.6vw,25px); line-height:1.55; }
    .buttons { display:flex; gap:10px; }
    button { appearance:none; border:1px solid var(--ink); border-radius:999px; padding:12px 18px; color:var(--ink); background:transparent; font:700 13px/1 system-ui,sans-serif; cursor:pointer; transition:transform .2s,background .2s,color .2s; white-space:nowrap; }
    button:hover { transform:translateY(-2px); background:var(--ink); color:var(--paper); }
    button.primary { color:var(--paper); background:var(--ink); }
    button.primary:hover { background:#1b493f; }
    @media (max-width:680px) { .card{min-height:calc(100vh - 48px);gap:32px}.footer{grid-template-columns:1fr}.buttons{width:100%}button{flex:1}.topline{align-items:flex-start;flex-direction:column}.translation{font-size:clamp(30px,10vw,48px)} }
    @media (prefers-reduced-motion:no-preference) { .frame{animation:rise .7s cubic-bezier(.2,.7,.2,1) both} main{animation:rise .8s .12s cubic-bezier(.2,.7,.2,1) both}@keyframes rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}} }
  </style>
</head>
<body>
  <div class="shell">
    <div class="frame">
      <article class="card">
        <header class="topline"><span class="mark">Daily Perspective</span><time id="date"></time></header>
        <main>
          <blockquote class="translation" id="quote">${translation}</blockquote>
          <p class="author">— ${author}</p>
          <p class="original" id="original">${english}</p>
        </main>
        <footer class="footer">
          <div><p class="label">TODAY'S PRACTICE</p><p class="action">${inspiration}</p></div>
          <div class="buttons"><button id="copy" type="button">複製金句</button><button class="primary" id="refresh" type="button">再抽一句</button></div>
        </footer>
      </article>
    </div>
  </div>
  <script>
    const date = new Intl.DateTimeFormat('zh-TW',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());
    document.getElementById('date').textContent = date;
    document.getElementById('refresh').addEventListener('click',()=>location.reload());
    document.getElementById('copy').addEventListener('click',async(event)=>{
      const authorText = document.querySelector('.author').textContent.replace('—', '').trim();
      const text = document.getElementById('quote').textContent + ' — ' + authorText;
      try { await navigator.clipboard.writeText(text); event.currentTarget.textContent='已複製'; setTimeout(()=>event.currentTarget.textContent='複製金句',1600); }
      catch { event.currentTarget.textContent='複製失敗'; }
    });
  </script>
</body>
</html>`;

return { json: { html } };
